import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 6
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record and record[0].startswith("\ufeff"):
            record[0] = record[0].lstrip("\ufeff")
        records.append(record)

    header_index = next(
        (i for i, record in enumerate(records) if len(record) == expected_width),
        None,
    )
    if header_index is None:
        header_index = next((i for i, record in enumerate(records) if record), 0)

    if not records:
        return {"columns": [], "rows": []}

    def normalize(record):
        values = list(record)
        if len(values) > expected_width:
            values = values[: expected_width - 1] + [",".join(values[expected_width - 1 :])]
        else:
            values.extend([""] * (expected_width - len(values)))
        return values

    columns = normalize(records[header_index])
    rows = [normalize(record) for record in records[header_index + 1 :]]
    return {"columns": columns, "rows": rows}
